type nodeMeasurement struct{}

// Info ...
// nolint:lll
func (*nodeMeasurement) Info() *inputs.MeasurementInfo {
	return &inputs.MeasurementInfo{
		Name:   "cbnode",
		Cat:    point.Metric,
		Desc:   "Couchbase node metrics, including node operation rate, item counts, uptime, memory usage, CPU usage, and cluster membership status.",
		DescZh: "Couchbase 节点指标，包含节点操作速率、项目数量、运行时长、内存使用、CPU 使用率和集群成员状态。",
		Fields: map[string]interface{}{
			"interestingstats_ops":                           &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.RequestsPerSec, Desc: "Total operations per second (including `XDCR`) to this bucket. (measured from cmd_get + cmd_set + incr_misses + incr_hits + decr_misses + decr_hits + delete_misses + delete_hits + ep_num_ops_del_meta + ep_num_ops_get_meta + ep_num_ops_set_meta)."},
			"interestingstats_curr_items":                    &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Current number of unique items in Couchbase."},
			"uptime":                                         &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.DurationSecond, Desc: "Time in seconds since this Couchbase node last started."},
			"interestingstats_couch_docs_data_size":          &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Bytes of active data in this bucket. (measured from couch_docs_data_size)."},
			"interestingstats_vb_active_number_non_resident": &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Interestingstats vb active number non resident."},
			"memory_total":                                   &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Total physical memory available on this Couchbase node in bytes."},
			"rebalance_start":                                &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of rebalance operations started on this Couchbase node."},
			"rebalance_success":                              &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of rebalance operations that completed successfully on this Couchbase node."},
			"systemstats_cpu_utilization_rate":               &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.Percent, Desc: "Percentage of CPU in use across all available cores on this server."},
			"systemstats_swap_total":                         &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Bytes of total swap space available on this server."},
			"systemstats_swap_used":                          &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Bytes of swap space in use on this server."},
			"graceful_failover_start":                        &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of graceful failover operations started on this Couchbase node."},
			"interestingstats_couch_views_actual_disk_size":  &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Bytes of active items in all the views for this bucket on disk (measured from couch_views_actual_disk_size)."},
			"memory_free":                                    &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Free physical memory currently available on this Couchbase node in bytes."},
			"failover":                                       &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of failover operations triggered for this Couchbase node."},
			"failover_complete":                              &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of failover operations that completed for this Couchbase node."},
			"healthy":                                        &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.Bool, Desc: "Whether this Couchbase node is currently reported as healthy, encoded as 0 or 1."},
			"systemstats_mem_free":                           &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Bytes of memory not in use on this server."},
			"interestingstats_couch_docs_actual_disk_size":   &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "The size of all data service files on disk for this bucket, including the data itself, metadata, and temporary files. (measured from couch_docs_actual_disk_size)."},
			"interestingstats_ep_bg_fetched":                 &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.RequestsPerSec, Desc: "Number of reads per second from disk for this bucket. (measured from ep_bg_fetched)."},
			"memcached_memory_reserved":                      &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Memory in bytes reserved for the memcached service on this Couchbase node."},
			"failover_incomplete":                            &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of failover operations that did not complete for this Couchbase node."},
			"interestingstats_curr_items_tot":                &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Current number of items in Couchbase including replicas."},
			"interestingstats_cmd_get":                       &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.RequestsPerSec, Desc: "Number of reads (get operations) per second from this bucket. (measured from cmd_get)."},
			"interestingstats_get_hits":                      &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.RequestsPerSec, Desc: "Number of get operations per second for data that this bucket contains. (measured from get_hits)."},
			"graceful_failover_success":                      &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of graceful failover operations that completed successfully on this Couchbase node."},
			"systemstats_mem_total":                          &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Bytes of total memory available on this server."},
			"interestingstats_couch_spatial_disk_size":       &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Interestingstats couch spatial disk size."},
			"interestingstats_couch_spatial_data_size":       &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Interestingstats couch spatial data size."},
			"interestingstats_couch_views_data_size":         &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Bytes of active data for all the views in this bucket. (measured from couch_views_data_size)."},
			"interestingstats_mem_used":                      &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Total memory used in bytes. (as measured from mem_used)."},
			"rebalance_failure":                              &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of rebalance operations that failed on this Couchbase node."},
			"rebalance_stop":                                 &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of rebalance operations stopped before completion on this Couchbase node."},
			"interestingstats_vb_replica_curr_items":         &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of items in replica vBuckets in this bucket. (measured from vb_replica_curr_items)."},
			"memcached_memory_allocated":                     &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Memory in bytes currently allocated by the memcached service on this Couchbase node."},
			"failover_node":                                  &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of node-level failover operations triggered for this Couchbase node."},
			"cluster_membership":                             &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.Bool, Desc: "Whether this node is currently a member of the Couchbase cluster, encoded as 0 or 1."},
			"graceful_failover_fail":                         &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of graceful failover operations that failed on this Couchbase node."},
		},
		Tags: map[string]interface{}{
			"host":     inputs.NewTagInfo("Host name."),
			"instance": inputs.NewTagInfo("Instance endpoint."),
			"cluster":  inputs.NewTagInfo("Cluster name."),
			"node":     inputs.NewTagInfo("Node ip."),
		},
	}
}

type bucketInfoMeasurement struct{}

// Info ...
// nolint:lll
func (*bucketInfoMeasurement) Info() *inputs.MeasurementInfo {
	return &inputs.MeasurementInfo{
		Name:   "cbbucketinfo",
		Cat:    point.Metric,
		Desc:   "Couchbase bucket summary metrics, including memory usage, operation rate, quota utilization, item count, disk usage, and resident item ratio.",
		DescZh: "Couchbase Bucket 概览指标，包含内存使用、操作速率、配额利用率、项目数量、磁盘使用和常驻项目比例。",
		Fields: map[string]interface{}{
			"basic_memused_bytes":      &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Current bucket memory usage in bytes."},
			"basic_opspersec":          &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.RequestsPerSec, Desc: "Current number of bucket operations executed per second."},
			"basic_quota_user_percent": &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.Percent, Desc: "Percentage of the bucket memory quota currently in use."},
			"basic_dataused_bytes":     &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Current bucket data size in bytes."},
			"basic_diskfetches":        &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Current number of disk fetch operations performed for this bucket."},
			"basic_diskused_bytes":     &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Current bucket disk usage in bytes."},
			"basic_itemcount":          &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "BucketItemCount first tries to retrieve an accurate bucket count via N1QL, but falls back to the REST API if that cannot be done (when there's no index to count all items in a bucket."},
		},
		Tags: map[string]interface{}{
			"host":     inputs.NewTagInfo("Host name."),
			"instance": inputs.NewTagInfo("Instance endpoint."),
			"bucket":   inputs.NewTagInfo("Bucket name."),
			"cluster":  inputs.NewTagInfo("Cluster name."),
		},
	}
}

type taskMeasurement struct{}

// Info ...
// nolint:lll
func (*taskMeasurement) Info() *inputs.MeasurementInfo {
	return &inputs.MeasurementInfo{
		Name:   "cbtask",
		Cat:    point.Metric,
		Desc:   "Couchbase background task metrics, including rebalance, compaction, recovery, XDCR, and index task progress.",
		DescZh: "Couchbase 后台任务指标，包含 rebalance、压缩、恢复、XDCR 和索引任务进度。",
		Fields: map[string]interface{}{
			"rebalance_progress":               &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Progress of a rebalance task."},
			"compacting_progress":              &inputs.FieldInfo{DataType: inputs.Int, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Progress of a bucket compaction task."},
			"xdcr_docs_checked":                &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of documents checked for changes."},
			"xdcr_docs_written":                &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of documents written to the destination cluster."},
			"xdcr_paused":                      &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Is this replication paused."},
			"active_vbuckets_left":             &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of Active VBuckets remaining."},
			"node_rebalance_progress":          &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Progress of a rebalance task per node."},
			"cluster_logs_collection_progress": &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Progress of a cluster logs collection task."},
			"xdcr_changes_left":                &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of updates still pending replication."},
			"xdcr_errors":                      &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of XDCR errors reported for this replication task."},
			"docs_total":                       &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Total number of documents considered by this task."},
			"docs_transferred":                 &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of documents transferred by this task."},
			"replica_vbuckets_left":            &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of Replica VBuckets remaining."},
		},
		Tags: map[string]interface{}{
			"host":     inputs.NewTagInfo("Host name."),
			"instance": inputs.NewTagInfo("Instance endpoint."),
			"bucket":   inputs.NewTagInfo("Bucket name."),
			"cluster":  inputs.NewTagInfo("Cluster name."),
			"node":     inputs.NewTagInfo("Node ip."),
			"source":   inputs.NewTagInfo("Source id."),
			"target":   inputs.NewTagInfo("Target id."),
		},
	}
}

type queryMeasurement struct{}

// Info ...
// nolint:lll
func (*queryMeasurement) Info() *inputs.MeasurementInfo {
	return &inputs.MeasurementInfo{
		Name:   "cbquery",
		Cat:    point.Metric,
		Desc:   "Couchbase N1QL query service metrics, including request errors, warnings, latency, throughput, and active request counts.",
		DescZh: "Couchbase N1QL 查询服务指标，包含请求错误、告警、延迟、吞吐和活跃请求数量。",
		Fields: map[string]interface{}{
			"errors":            &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of N1QL query requests that failed."},
			"warnings":          &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of N1QL query requests that completed with warnings."},
			"avg_req_time":      &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.DurationMS, Desc: "Average end-to-end time in milliseconds to complete a N1QL query request."},
			"invalid_requests":  &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of invalid N1QL query requests rejected by the service."},
			"request_time":      &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.DurationMS, Desc: "Total N1QL request processing time in milliseconds."},
			"requests_5000ms":   &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.RequestsPerSec, Desc: "Number of N1QL query requests per second whose latency exceeds 5000 milliseconds."},
			"result_count":      &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of rows returned by N1QL query requests."},
			"service_time":      &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.DurationMS, Desc: "Time in milliseconds spent by the N1QL engine executing queries, excluding time waiting in the request queue."},
			"avg_response_size": &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Average response payload size in bytes returned by N1QL query requests."},
			"queued_requests":   &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Current number of N1QL query requests waiting in the service queue."},
			"requests":          &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Total number of N1QL query requests handled by the service."},
			"requests_250ms":    &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.RequestsPerSec, Desc: "Number of N1QL query requests per second whose latency exceeds 250 milliseconds."},
			"requests_500ms":    &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.RequestsPerSec, Desc: "Number of N1QL query requests per second whose latency exceeds 500 milliseconds."},
			"avg_svc_time":      &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.DurationMS, Desc: "Average query execution time in milliseconds inside the N1QL service."},
			"avg_result_count":  &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Average number of rows returned per N1QL query request."},
			"active_requests":   &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Current number of N1QL query requests actively executing."},
			"requests_1000ms":   &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.RequestsPerSec, Desc: "Number of N1QL query requests per second whose latency exceeds 1000 milliseconds."},
			"result_size":       &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Total size in bytes of rows returned by N1QL query requests."},
			"selects":           &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of N1QL query requests that execute a SELECT statement."},
		},
		Tags: map[string]interface{}{
			"host":     inputs.NewTagInfo("Host name."),
			"instance": inputs.NewTagInfo("Instance endpoint."),
			"cluster":  inputs.NewTagInfo("Cluster name."),
		},
	}
}

type indexMeasurement struct{}

// Info ...
// nolint:lll
func (*indexMeasurement) Info() *inputs.MeasurementInfo {
	return &inputs.MeasurementInfo{
		Name:   "cbindex",
		Cat:    point.Metric,
		Desc:   "Couchbase index service metrics, including memory quota, remaining RAM, index fragmentation, item counts, scan rates, and indexer state.",
		DescZh: "Couchbase 索引服务指标，包含内存配额、剩余内存、索引碎片率、项目数量、扫描速率和索引器状态。",
		Fields: map[string]interface{}{
			"memory_quota":            &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Index Service memory quota."},
			"remaining_ram":           &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Bytes of Index RAM quota still available on this server."},
			"frag_percent":            &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.Percent, Desc: "Percentage fragmentation of the index."},
			"num_rows_returned":       &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Total number of rows returned so far by the indexer."},
			"resident_percent":        &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.Percent, Desc: "Percentage of the data held in memory."},
			"num_docs_indexed":        &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of documents indexed by the indexer since last startup."},
			"items_count":             &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "The number of items currently indexed."},
			"num_docs_pending_queued": &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of documents pending to be indexed."},
			"avg_scan_latency":        &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.DurationNS, Desc: "Average time to serve a scan request (nanoseconds)."},
			"cache_misses":            &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Accesses to this index data from disk."},
			"cache_hit_percent":       &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.Percent, Desc: "Percentage of memory accesses that were served from the managed cache."},
			"memory_used":             &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.SizeByte, Desc: "Index Service memory used."},
			"ram_percent":             &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.Percent, Desc: "Percentage of Index RAM quota in use across all indexes on this server."},
			"num_requests":            &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Number of requests served by the indexer since last startup."},
			"cache_hits":              &inputs.FieldInfo{DataType: inputs.Float, Type: inputs.Gauge, Unit: inputs.NCount, Desc: "Accesses to this index data from RAM."},
		},
		Tags: map[string]interface{}{
			"host":     inputs.NewTagInfo("Host name."),
			"instance": inputs.NewTagInfo("Instance endpoint."),
			"cluster":  inputs.NewTagInfo("Cluster name."),
			"keyspace": inputs.NewTagInfo("Key space name."),
		},
	}
}

